/* @lc app=leetcode id=3660 lang=kotlin */ class Solution { fun maxValue(nums: IntArray): IntArray = nums.size.let { n -> nums.runningFold(0) { a, b -> maxOf(a, b) }.drop(1).let { pm -> nums.reversed().runningFold(Int.MAX_VALUE) { a, b -> minOf(a, b) }.drop(1).reversed().let { sm -> (n - 1 downTo 0).fold(IntArray(n)) { ans, i -> ans.also { it[i] = if (i < n - 1 && pm[i] > sm[i + 1]) it[i + 1] else pm[i] } } } } } }